from dataclasses import dataclass
from datetime import datetime, timedelta
from statistics import median

@dataclass
class Deploy:
    service: str
    committed_at: datetime     # when the shipped change was committed
    deployed_at: datetime
    failed: bool               # needed immediate rollback or hotfix
    recovered_at: datetime | None = None
    unplanned: bool = False    # shipped to fix a production incident

def hours(delta: timedelta) -> float:
    return delta / timedelta(hours=1)

def dora(deploys: list[Deploy], days: int) -> dict:
    # Input: ONE service over a period. Never group by author.
    failed = [d for d in deploys if d.failed]
    return {
        "deploys_per_day": len(deploys) / days,
        "lead_time_h": median(hours(d.deployed_at - d.committed_at) for d in deploys),
        "change_fail_rate": len(failed) / len(deploys),
        "recovery_h": median(hours(d.recovered_at - d.deployed_at) for d in failed) if failed else 0.0,
        "rework_rate": sum(d.unplanned for d in deploys) / len(deploys),
    }
